style.css:
@-moz-document domain("scriptblox.com") {
:root {
        --my-bg: #020719;
        --my-panel: rgba(3, 15, 42, 0.78);
        --my-blue: #087cff;
        --my-cyan: #45cfff;
        --my-text: #e3f2ff;
    }

    /* starry wallpaper */
    html,
    body {
        background: #020719 url("https://wallpaperaccess.com/full/212745.jpg") center center / cover fixed no-repeat !important;
        color: var(--my-text) !important;
        font-family: "Segoe UI", sans-serif !important;
    }

    /* midnight panels */
    main,
    section,
    article,
    nav,
    aside {
        background-color: var(--my-panel) !important;
        color: var(--my-text) !important;
    }

    /* glowing links */
    a {
        color: var(--my-cyan) !important;
        transition: 0.2s ease !important;
    }

    a:hover {
        color: white !important;
        text-shadow: 0 0 10px var(--my-cyan) !important;
    }

    /* glowing buttons */
    button {
        background: linear-gradient(135deg, #0755c9, #079eff) !important;
        color: white !important;
        border: 1px solid rgba(69, 207, 255, 0.5) !important;
        border-radius: 9px !important;
    }

    button:hover {
        box-shadow: 0 0 16px rgba(69, 207, 255, 0.65) !important;
    }

    /* inputs */
    input,
    textarea,
    select {
        background: rgba(2, 12, 34, 0.9) !important;
        color: white !important;
        border: 1px solid #126bc5 !important;
        border-radius: 8px !important;
    }

    /* scrollbar */
    ::-webkit-scrollbar {
        width: 9px !important;
    }

    ::-webkit-scrollbar-track {
        background: #020719 !important;
    }

    ::-webkit-scrollbar-thumb {
        background: linear-gradient(#087cff, #45cfff) !important;
        border-radius: 20px !important;
    }
}
